{
  "items": [
    {
      "name": "MvPolynomial.comp_aeval",
      "type": " {R : Type u} {S₁ : Type v} {σ : Type u_1} [CommSemiring R] [CommSemiring S₁] [Algebra R S₁] (f : σ → S₁) {B : Type u_2} [CommSemiring B] [Algebra R B] (φ : S₁ →ₐ[R] B) : φ.comp (MvPolynomial.aeval f) = MvPolynomial.aeval fun i => φ (f i)",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.aeval_comp_rename",
      "type": " {σ : Type u_1} {τ : Type u_2} {R : Type u_4} {S : Type u_5} [CommSemiring R] [CommSemiring S] (k : σ → τ) (g : τ → S) [Algebra R S] : (MvPolynomial.aeval g).comp (MvPolynomial.rename k) = MvPolynomial.aeval (g ∘ k)",
      "module": "Mathlib.Algebra.MvPolynomial.Rename"
    },
    {
      "name": "MvPolynomial.aeval_comp_toMvPolynomial",
      "type": " {R : Type u_1} {S : Type u_2} {σ : Type u_3} [CommSemiring R] [CommSemiring S] [Algebra R S] (f : σ → S) (i : σ) : (MvPolynomial.aeval f).comp (Polynomial.toMvPolynomial i) = Polynomial.aeval (f i)",
      "module": "Mathlib.Algebra.MvPolynomial.Equiv"
    },
    {
      "name": "MvPolynomial.aeval_comp_bind₁",
      "type": " {σ : Type u_1} {τ : Type u_2} {R : Type u_3} {S : Type u_4} [CommSemiring R] [CommSemiring S] [Algebra R S] (f : τ → S) (g : σ → MvPolynomial τ R) : (MvPolynomial.aeval f).comp (MvPolynomial.bind₁ g) = MvPolynomial.aeval fun i => (MvPolynomial.aeval f) (g i)",
      "module": "Mathlib.Algebra.MvPolynomial.Monad"
    },
    {
      "name": "AlgebraicIndependent.aeval_comp_repr",
      "type": " {ι : Type u_1} {R : Type u_3} {A : Type u_4} {x : ι → A} [CommRing R] [CommRing A] [Algebra R A] (hx : AlgebraicIndependent R x) : (MvPolynomial.aeval x).comp hx.repr = (Algebra.adjoin R (Set.range x)).val",
      "module": "Mathlib.RingTheory.AlgebraicIndependent.Defs"
    },
    {
      "name": "AlgebraicIndependent.liftAlgHom_comp_reprField",
      "type": " {ι : Type u_1} {F : Type u_2} {E : Type u_3} {x : ι → E} [Field F] [Field E] [Algebra F E] (hx : AlgebraicIndependent F x) : (IsFractionRing.liftAlgHom ⋯).comp hx.reprField = (IntermediateField.adjoin F (Set.range x)).val",
      "module": "Mathlib.RingTheory.AlgebraicIndependent.Adjoin"
    },
    {
      "name": "AlgebraicIndependent.aeval_comp_mvPolynomialOptionEquivPolynomialAdjoin",
      "type": " {ι : Type u} {R : Type u_2} {A : Type v} {x : ι → A} [CommRing R] [CommRing A] [Algebra R A] (hx : AlgebraicIndependent R x) (a : A) : (AlgHom.restrictScalars R (Polynomial.aeval a)).comp ↑hx.mvPolynomialOptionEquivPolynomialAdjoin = MvPolynomial.aeval fun o => o.elim a x",
      "module": "Mathlib.RingTheory.AlgebraicIndependent.Basic"
    },
    {
      "name": "MvPolynomial.aeval_comp_expand",
      "type": " {σ : Type u_1} {R : Type u_3} [CommSemiring R] (p : ℕ) {A : Type u_5} [CommSemiring A] [Algebra R A] (f : σ → A) : (MvPolynomial.aeval f).comp (MvPolynomial.expand p) = MvPolynomial.aeval (f ^ p)",
      "module": "Mathlib.Algebra.MvPolynomial.Expand"
    },
    {
      "name": "MvPolynomial.expand_zero",
      "type": " {σ : Type u_1} {R : Type u_3} [CommSemiring R] : MvPolynomial.expand 0 = (Algebra.ofId R (MvPolynomial σ R)).comp (MvPolynomial.aeval 1)",
      "module": "Mathlib.Algebra.MvPolynomial.Expand"
    }
  ]
}
